// Get employee information from previous node
const employee = $input.first().json;

// Employee basic information
const employeeId = employee.employee_id || employee['Employee ID'];
const employeeName = employee.name || employee['Employee Name'];
const department = employee.department || employee.Department;
const employeeEmail = employee.email || employee['Employee Email'];
const lastWorkingDate =
  employee.last_working_date || employee['Last Working Date'];

// Common IT tasks
const itTasks = [
  {
    task_name: 'Disable company email',
    priority: 'High',
    department: 'IT'
  },
  {
    task_name: 'Collect company laptop',
    priority: 'High',
    department: 'IT'
  },
  {
    task_name: 'Remove Slack access',
    priority: 'High',
    department: 'IT'
  },
  {
    task_name: 'Remove VPN access',
    priority: 'High',
    department: 'IT'
  }
];

// Additional tasks based on department
if (department === 'Engineering') {
  itTasks.push(
    {
      task_name: 'Remove GitLab access',
      priority: 'High',
      department: 'IT'
    },
    {
      task_name: 'Remove development environment access',
      priority: 'High',
      department: 'IT'
    }
  );
}

if (department === 'Finance') {
  itTasks.push({
    task_name: 'Remove accounting system access',
    priority: 'High',
    department: 'IT'
  });
}

// HR tasks
const hrTasks = [
  {
    task_name: 'Collect resignation letter',
    priority: 'Medium',
    department: 'HR'
  },
  {
    task_name: 'Complete exit interview',
    priority: 'Medium',
    department: 'HR'
  },
  {
    task_name: 'Calculate final settlement',
    priority: 'High',
    department: 'HR'
  },
  {
    task_name: 'Collect company assets',
    priority: 'High',
    department: 'HR'
  },
  {
    task_name: 'Prepare experience letter',
    priority: 'Medium',
    department: 'HR'
  },
  {
    task_name: 'Update employee records',
    priority: 'Medium',
    department: 'HR'
  }
];

// Add common information to every task
const allTasks = [
  ...itTasks.map(task => ({
    ...task,
    employee_id: employeeId,
    employee_name: employeeName,
    employee_email: employeeEmail,
    last_working_date: lastWorkingDate
  })),

  ...hrTasks.map(task => ({
    ...task,
    employee_id: employeeId,
    employee_name: employeeName,
    employee_email: employeeEmail,
    last_working_date: lastWorkingDate
  }))
];

// Return one item containing the complete checklist
return [
  {
    json: {
      employee_id: employeeId,
      employee_name: employeeName,
      employee_email: employeeEmail,
      department: department,
      last_working_date: lastWorkingDate,

      it_tasks: itTasks,
      hr_tasks: hrTasks,

      total_it_tasks: itTasks.length,
      total_hr_tasks: hrTasks.length,
      total_tasks: allTasks.length,

      all_tasks: allTasks
    }
  }
];

