// Get all task items from the previous node
const items = $input.all();

// Extract and normalize task data
const tasks = items.map(item => {
  const data = item.json;

  // Handle different possible status formats
  let status = data.status;

  if (typeof status === 'object' && status !== null) {
    status =
      status.status ||
      status.name ||
      status.label ||
      status.type ||
      '';
  }

  // Always convert status to string
  status = String(status || '').toLowerCase().trim();

  return {
    task_id: data.task_id || data.id || '',
    name: data.name || data.task_name || '',
    status: status
  };
});

// Statuses considered completed
const completedStatuses = [
  'complete',
  'completed',
  'done',
  'closed'
];

// Separate completed and pending tasks
const completedTasks = tasks.filter(task =>
  completedStatuses.includes(task.status)
);

const pendingTasks = tasks.filter(task =>
  !completedStatuses.includes(task.status)
);

// Calculate totals
const totalTasks = tasks.length;
const completedCount = completedTasks.length;
const pendingCount = pendingTasks.length;

const completionPercentage = totalTasks > 0
  ? Number(((completedCount / totalTasks) * 100).toFixed(2))
  : 0;

// Determine overall status
let overallStatus;

if (pendingCount === 0) {
  overallStatus = 'COMPLETED';
} else if (completedCount === 0) {
  overallStatus = 'PENDING';
} else {
  overallStatus = 'PARTIALLY_COMPLETED';
}

// Return ONE item
return [
  {
    json: {
      total_tasks: totalTasks,
      completed_tasks: completedCount,
      pending_tasks: pendingCount,
      completion_percentage: completionPercentage,
      overall_status: overallStatus,

      completed_task_list: completedTasks,
      pending_task_list: pendingTasks,

      all_tasks: tasks
    }
  }
];

// Get the output from Node 10
const data = $input.first().json;

// Get pending tasks
const pendingTasks = data.pending_task_list || [];

// Create pending task list for Slack
const taskList = pendingTasks.map((task, index) => {
  return `${index + 1}. ❌ ${task.name} — ${task.status}`;
}).join('\n');

// Create Slack message
const slackMessage = `⚠️ *Employee Offboarding Escalation*

*Task Completion Summary*
━━━━━━━━━━━━━━━━━━━━
📋 Total Tasks: ${data.total_tasks}
✅ Completed: ${data.completed_tasks}
⏳ Pending: ${data.pending_tasks}
📊 Completion: ${data.completion_percentage}%

*Pending Tasks*
━━━━━━━━━━━━━━━━━━━━
${taskList}

⚠️ Please complete the pending offboarding tasks as soon as possible.`;

// Return one item
return [
  {
    json: {
      slack_message: slackMessage,
      pending_tasks: data.pending_tasks,
      completion_percentage: data.completion_percentage,
      overall_status: data.overall_status
    }
  }
];
